if(u.pathname==='/api/model-config'){if(request.method==='GET'){let c=await env.DB.prepare('SELECT payload FROM settings WHERE id=?').bind('model').first(),config=c?JSON.parse(c.payload):{provider:'openai',model:'',maxBudget:1,inputPrice:0,outputPrice:0};return json({config,configured:!!(PROVIDERS[config.provider]&&env[PROVIDERS[config.provider].secret]&&config.model&&((config.inputPrice>0&&config.outputPrice>0)||(config.provider==='siliconflow'&&FREE_SILICONFLOW_MODELS.includes(config.model)))),inferenceImplemented:true,reason:'密钥仅保存在服务器；没有密钥时不会调用模型'});}let c=await body(request);if(Object.keys(c).some(k=>!['provider','model','maxBudget','inputPrice','outputPrice'].includes(k)))throw Error('不接收密钥或未知字段');if(!['openai','deepseek','qwen','siliconflow'].includes(c.provider)||typeof c.model!=='string'||c.model.length>100||!Number.isFinite(c.maxBudget)||c.maxBudget<0||c.maxBudget>1000||!Number.isFinite(c.inputPrice)||c.inputPrice<0||c.inputPrice>1000||!Number.isFinite(c.outputPrice)||c.outputPrice<0||c.outputPrice>1000)throw Error('模型配置无效');await env.DB.prepare('INSERT INTO settings(id,payload) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload').bind('model',JSON.stringify(c)).run();return json({config:c,configured:false,inferenceImplemented:true});}
