if(u.pathname==='/api/news-enrich'&&request.method==='POST'){let input=await body(request),d=structuredClone(await dataset(env.DB,input.datasetId));let result=await collectByd({urls:input.urls,mode:'observed_only'});let selected=result.documents.filter(x=>d.stocks.some(s=>s.code===x.code)&&x.publicationDate>=d.start&&x.publicationDate<=d.end);if(!selected.length)throw Error('已读取来源，但无符合所选股票及日期范围的新闻元数据；未创建空副本');d.documents=[...new Map([...d.documents,...selected].map(x=>[x.url||x.id,x])).values()];d.sources.push(...result.provenance.map(x=>({...x,kind:'比亚迪官方新闻元数据'})));d.warnings.push(...result.warnings);d.coverage.push({kind:'比亚迪官方新闻元数据',code:'002594',complete:false,documentCount:selected.length,note:'用户提供来源链接的小批次导入；不是自动搜索或完整档案'});validateDataset(d);d.parentDatasetId=input.datasetId;d.collectedAt=new Date().toISOString();d.digest=await sha256(JSON.stringify(d));let did=id();await env.DB.prepare('INSERT INTO datasets(id,created,payload) VALUES(?,?,?)').bind(did,d.collectedAt,JSON.stringify(d)).run();return json({id:did,dataset:d,added:selected.length});}
if(u.pathname==='/api/stocks'&&request.method==='GET')return json(searchCatalogue(await loadCatalogue(env.DB),Object.fromEntries(u.searchParams)));
if(u.pathname==='/api/status')return json({ai:{configured:false,reason:'API 预留，未配置任何模型或密钥'},universeMode:'full_catalogue',recommendedStocks:RECOMMENDED_STOCKS,recommendedDays:120,collectionChunkDays:COLLECTION_CHUNK_DAYS,engineVersion:'2.0.0',storage:'D1',news:'bounded_search_excerpts'});
if(u.pathname==='/api/datasets'&&request.method==='GET'){let rows=await env.DB.prepare('SELECT id,created,payload FROM datasets ORDER BY created DESC LIMIT 20').all();return json(rows.results.map(x=>{let d=JSON.parse(x.payload);return{id:x.id,created:x.created,start:d.start,end:d.end,stocks:d.stocks.map(s=>({code:s.code,name:s.name})),digest:d.digest};}));}
if(u.pathname==='/api/collection-jobs'&&request.method==='GET'){let rows=await env.DB.prepare('SELECT id,payload,version FROM collection_jobs ORDER BY updated DESC LIMIT 20').all();return json(rows.results.map(x=>({id:x.id,version:x.version,...JSON.parse(x.payload)})));}
